INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 11, 'theory', 'Quiz: bond, MTU and ethtool');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 0, 'A bond has miimon 100 and you set downdelay 250. How many milliseconds after detecting the carrier loss will the driver wait before declaring the slave failed?', '["250", "100", "200", "300"]', 2, 'Delays are counted in polling periods, so the value is rounded down to a multiple of miimon: 250 becomes 200. It is better to set multiples right away.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 1, 'What does the [fixed] mark next to an offload in the output of ethtool -k mean?', '["The driver or the card does not let you change this offload", "The offload is on for good and cannot be off", "A change was requested but is not applied yet", "The offload is pinned in the NetworkManager configuration"]', 0, 'The [fixed] mark appears when the card has no such feature or it cannot be changed; the value may be on or off. A requested but unapplied change looks like [requested on] or [requested off].');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 2, 'Why does the layer3+4 policy not give one TCP connection the speed of two bond interfaces?', '["Ports are not part of the hash", "It works for UDP only", "The hash is recomputed for every packet", "One connection has a constant hash, so it always goes through one interface"]', 3, 'The addresses and ports of a connection do not change, so neither does the hash result. Different connections spread out, but one stays on its interface. Only balance-rr stripes one connection, at the price of reordering.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 3, 'What is the largest value of -s that passes with ping -M do -s N over an IPv4 link with MTU 1500?', '["1500", "1472", "1464", "1450"]', 1, 'Ping adds an 8-byte ICMP header and a 20-byte IPv4 header, 28 in all. So 1500 minus 28 is 1472; with 1473 the kernel answers message too long.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 4, 'In an 802.3ad bond one slave has an Aggregator ID different from the active aggregator and a zero partner MAC. What is the most likely cause?', '["miimon is too large", "The layer2 policy is chosen", "The switch does not run LACP on this port: it is in the wrong channel or LACP is off", "updelay is too short"]', 2, 'A zero partner MAC means no LACPDUs arrive from the neighbor, and the port forms an aggregator of its own. The cause is usually on the switch side or in the cable; miimon and the hash do not affect it.');
